def refs():
    return [{**s, "subject": "science", "observedPattern": "公立學校公開自然／理化試題常以四顆類地行星的距日距離、組成、重力、大氣、溫度與水文線索考查比較推理；本題只取能力方向並重新設計情境、資料與選項。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


