Q = [
    make(1, "下列哪一組天體都是類地行星？", {"A": "水星、金星、地球、火星", "B": "木星、土星、天王星、海王星", "C": "太陽、地球、月球、火星", "D": "金星、木星、土星、彗星"}, "A", "類地行星是水星、金星、地球與火星，通常具有岩石金屬組成和固體表面；後四顆八大行星通常歸為類木行星。", "先確認題目問的是分類共同特徵，再排除恆星、衛星與類木行星。", ["列出八大行星的內外順序。", "辨認靠近太陽的前四顆。", "它們主要由岩石與金屬組成。", "太陽不是行星，月球是衛星。", "所以類地行星組合是水星、金星、地球、火星。"], "easy"),
    make(2, "『類地行星』這個分類名稱主要表示什麼？", {"A": "四顆行星的環境都適合人類居住", "B": "四顆行星都擁有厚大氣與液態水", "C": "四顆行星的組成與結構有岩石金屬、固體表面等共同特徵", "D": "四顆行星都與地球距離相同"}, "C", "類地是依組成和結構的分類，表示岩石金屬、固體表面、相對較小等共同特徵，不保證環境或宜居性相同。", "分清分類回答共同特徵，環境比較則需另外看距離、大氣與歷史。", ["先找『類地』的分類依據。", "四顆行星都有岩石金屬與固體表面。", "它們的環境仍可有很大差異。", "金星與水星可反駁宜居保證。", "所以選組成與結構共同特徵。"], "easy"),
    make(3, "水星幾乎沒有濃厚大氣，且白天與夜晚表面溫差很大，哪項因素可協助解釋？", {"A": "大氣稀薄，保溫與熱量搬運作用弱，且重力較難長久保留氣體", "B": "水星有最厚的二氧化碳雲層", "C": "水星表面全部是液態水", "D": "水星距太陽最遠"}, "A", "水星質量與重力較小，難以長久保留濃厚大氣；大氣稀薄也使日夜間熱量調節弱，溫差可很大。", "把觀測現象連到大氣保留與熱量搬運條件，不只看距日距離。", ["確認水星大氣極稀薄。", "較小的重力較難保留氣體。", "稀薄大氣無法有效搬運與保存熱量。", "日照面與背陽面的差異因此較明顯。", "所以選大氣稀薄與重力保留能力的解釋。"], "medium"),
    make(4, "金星距離太陽比水星遠，表面卻極為炎熱，這最能提醒我們？", {"A": "表面溫度只由距日距離決定", "B": "金星沒有任何大氣", "C": "距離太陽越遠一定越熱", "D": "濃厚、二氧化碳為主的大氣造成強烈溫室效應，不能只看距離"}, "D", "金星擁有濃厚大氣與大量二氧化碳，強烈溫室效應能使表面保持極高溫；距日距離只是收到太陽能量的背景因素。", "比較多個成因變因，避免用單一距日距離包辦表面溫度。", ["確認金星距太陽距離不是唯一資料。", "檢查金星大氣厚度與成分。", "二氧化碳濃厚大氣可造成強烈溫室效應。", "溫室效應會改變表面能量平衡。", "所以不能只用距離判定溫度。"], "medium"),
    make(5, "火星現在表面寒冷乾燥，但發現古河道地形，較合理的推論是？", {"A": "火星歷史上可能曾有流水活動，但仍需其他證據確認細節", "B": "火星現在乾燥，所以歷史上絕不可能有水", "C": "古河道一定由液態金屬形成", "D": "照片顏色已直接證明火星有生命"}, "A", "古河道和相關礦物、沉積地形可作為過去可能有流水的線索，但屬推論證據，不能由單一地形直接確定完整歷史或生命。", "分開現在觀測狀態與過去推論，並標示證據強度。", ["記錄現在火星寒冷乾燥。", "辨認古河道是過去流水的可能線索。", "現況不等於完整歷史。", "需要礦物、沉積與年代等其他資料交叉驗證。", "因此只能推論過去可能有流水。"], "medium"),
    make(6, "若一顆行星質量較小、重力較弱，對長期保留濃厚大氣通常有何影響？", {"A": "較難保留氣體，但不能只靠重力單獨判定大氣狀態", "B": "一定會有最厚大氣", "C": "重力弱會自動產生液態水", "D": "重力與大氣保留完全無關"}, "A", "較弱重力通常較難長期留住氣體，但大氣成分、溫度、太陽風、磁場與地質活動也會影響結果，不能只看單一因素。", "先指出重力的作用，再補上模型的其他條件與限制。", ["確認質量與重力是大氣保留的相關條件。", "重力較弱時氣體逃逸可能較容易。", "但大氣狀態還受成分與溫度影響。", "太陽風、磁場與地質活動也可能改變大氣。", "所以只能作較難保留的有條件推論。"], "hard"),
    make(7, "下列哪一項最能說明『類地』不等於『適合人類居住』？", {"A": "金星同屬類地行星，但表面有濃厚大氣與極端高溫", "B": "四顆行星都由岩石金屬組成", "C": "地球屬於類地行星", "D": "水星也是太陽系天體"}, "A", "類地分類表示組成與結構相近，不保證表面溫度、大氣壓力、液態水或生命條件；金星是明顯反例。", "找出同分類但環境不同的反例，區分分類語意和宜居條件。", ["確認金星屬於類地行星。", "檢查類地分類描述的是組成與結構。", "金星表面有厚大氣與極高溫。", "這些條件不等於人類可居住。", "因此金星反例最能支持該結論。"], "medium"),
    make(8, "假想探測表顯示：甲距日最近且大氣極稀薄；乙大小近地球但二氧化碳厚大氣；丙有液態水與氮氧大氣；丁有古河道且大氣稀薄。合理配對為？", {"A": "甲火星、乙水星、丙金星、丁地球", "B": "甲金星、乙火星、丙水星、丁地球", "C": "甲水星、乙金星、丙地球、丁火星", "D": "甲地球、乙火星、丙水星、丁金星"}, "C", "水星最靠近太陽且大氣極稀薄；金星大小近地球但二氧化碳厚大氣；地球有液態水和氮氧大氣；火星有古河道和稀薄大氣。", "把每欄特徵分別配對，再用整組條件互相檢查。", ["用距日最近與稀薄大氣配對水星。", "用近地球大小、厚二氧化碳大氣配對金星。", "用液態水和氮氧大氣配對地球。", "剩下古河道與稀薄大氣配對火星。", "因此選甲水星、乙金星、丙地球、丁火星。"], "hard"),
    make(9, "若資料只給某行星距離太陽較遠，最穩妥能提出的結論是？", {"A": "它表面一定比所有行星冷", "B": "它收到的太陽能量背景可能不同，但表面溫度仍需大氣等資料", "C": "它一定沒有大氣", "D": "它一定有液態水"}, "B", "距日距離可影響接收太陽能量的背景，但表面溫度還受大氣成分、溫室效應、地質與自轉等影響，不能單獨決定。", "把資料能支持的背景因素和需要額外證據的環境結論分開。", ["確認已知資料只有距日距離。", "距離會影響接收太陽能量的背景。", "表面溫度還取決於大氣與能量平衡。", "液態水與大氣也不能由距離直接推出。", "所以選有條件的距日解讀。"], "hard"),
    make(10, "比較四顆類地行星環境時，哪一種資料判讀流程較可靠？", {"A": "只看照片顏色決定溫度與水量", "B": "先確認共同組成，再同時比較距日距離、質量、重力、大氣與表面證據", "C": "只用距日距離解釋所有差異", "D": "只要行星大小接近地球就判定宜居"}, "B", "可靠比較要先用組成和結構判斷類地共同特徵，再交叉讀取距離、質量、重力、大氣與表面歷史資料；單一照片或因素不足。", "採用共同分類→多變因比較→證據限制的順序。", ["先找四顆行星的共同岩石金屬與固體表面。", "再比較距日距離與收到的能量背景。", "檢查質量、重力和大氣保留條件。", "加入溫度、水狀態與地質歷史證據。", "最後標示僅由部分資料不能推出的結論。"], "hard"),
]

